    subhead: "Start lean, then add capacity when the signal is clear.",
    currency: "$",
    billing: { monthly: "Bill monthly", yearly: "Bill annually", saving: "\u221220%" },
    plans: [
        { name: "Launch", description: "For small teams turning their first repeatable process live.", price: 29, yearlyPrice: 23, period: "/ month", note: "Billed month to month", yearlyNote: "Billed annually \u00B7 {total}", features: ["Three active workspaces", "25k monthly runs", "Core integrations", "Seven-day activity history", "Community support"], cta: { label: "Start building", href: "#" } },
        { name: "Scale", description: "For product teams that need more control as volume grows.", price: 79, yearlyPrice: 63, period: "/ month", note: "Billed month to month", yearlyNote: "Billed annually \u00B7 {total}", features: ["Everything in Launch", "Unlimited workspaces", "500k monthly runs", "Advanced permissions", "Priority support"], cta: { label: "Choose Scale", href: "#" }, featured: true },
        { name: "Enterprise", description: "For organizations with custom security and scale requirements.", priceLabel: "Custom pricing", note: "Annual agreement", features: ["Everything in Scale", "SAML and directory sync", "Custom data retention", "Security review support", "Dedicated success lead"], cta: { label: "Talk to sales", href: "#" } },
