        <div className="art:relative art:mx-auto art:max-w-6xl">
          <motion.header className="art:mx-auto art:flex art:max-w-4xl art:flex-col art:items-center art:text-center" initial={{ opacity: 0, y: 18 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.6 }} transition={{ duration: 0.7, ease: ARTEMIS_EASE_OUT, y: reduced ? { duration: 0 } : undefined }}>
            {copy.badge && <div className="art:inline-flex art:items-center art:gap-3 art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.16em]">
              <span className="art:grid art:size-5 art:place-items-center art:bg-foreground/[0.06]">
                <span className="art:size-1.5 art:bg-primary"/>
              </span>
              <span className="art:border art:border-border/45 art:px-3 art:py-1.5">
                {copy.badge}
              </span>
            </div>}
            <h2 className="art:mt-7 art:text-balance art:leading-tight art:tracking-[-0.055em] art:text-4xl art:font-medium">
              {copy.headline}
            </h2>
            {copy.subhead && <p className="art:mt-6 art:max-w-xl art:text-balance art:font-mono art:text-xs art:text-muted-foreground art:leading-6 art:@min-[640px]/artemis:text-sm">
              {copy.subhead}
            </p>}
            {copy.billing && <fieldset className="art:mt-9 art:flex art:border art:border-border/45 art:bg-foreground/[0.035] art:p-1 art:[background-image:repeating-linear-gradient(135deg,color-mix(in_oklch,var(--artemis-foreground)_3%,transparent)_0,color-mix(in_oklch,var(--artemis-foreground)_3%,transparent)_1px,transparent_1px,transparent_7px)]">
              <legend className="art:sr-only">
                {"Billing period"}
              </legend>
              <motion.button onClick={() => setAnnual(true)} whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} type="button" className={`art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:inline-block art:h-auto art:p-0 art:font-normal art:hover:bg-transparent art:relative art:min-h-9 art:min-w-28 art:px-5 art:font-mono art:text-xs art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-primary art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:@min-[640px]/artemis:min-w-36 art:rounded-full ${annual ? "art:hover:text-inherit art:text-primary-foreground" : "art:text-muted-foreground art:hover:text-foreground"}`} aria-pressed={annual} tabIndex={0}>
                {annual && <motion.span layoutId={billingId} className="art:absolute art:inset-0 art:bg-primary" transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}/>}
                <span className="art:relative">
                  {copy.billing.saving ? `${copy.billing.yearly} \u00B7 ${copy.billing.saving}` : copy.billing.yearly}
                </span>
              </motion.button>
              <motion.button onClick={() => setAnnual(false)} whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} type="button" className={`art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:inline-block art:h-auto art:p-0 art:font-normal art:hover:bg-transparent art:relative art:min-h-9 art:min-w-28 art:px-5 art:font-mono art:text-xs art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-primary art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:@min-[640px]/artemis:min-w-36 art:rounded-full ${!annual ? "art:hover:text-inherit art:text-primary-foreground" : "art:text-muted-foreground art:hover:text-foreground"}`} aria-pressed={!annual} tabIndex={0}>
                {!annual && <motion.span layoutId={billingId} className="art:absolute art:inset-0 art:bg-primary" transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}/>}
                <span className="art:relative">
                  {copy.billing.monthly}
                </span>
              </motion.button>
            </fieldset>}
          </motion.header>
          <div className="art:mt-20 art:grid art:gap-10 art:@min-[1024px]/artemis:grid-cols-3 art:@min-[1024px]/artemis:gap-8">
            {plans.map((plan, index) => {
                const price = (annual ? plan.yearlyPrice : undefined) ?? plan.price ?? 0;
                const note = annual && plan.yearlyNote !== undefined ? plan.yearlyNote.replace("{total}", `${copy.currency}${Math.round(price * 1200) / 100}`) : plan.note;
                return <motion.article key={index} className={plan.featured ? "art:relative art:flex art:min-h-[32rem] art:flex-col art:border art:bg-background art:border-primary/35" : "art:relative art:flex art:min-h-[32rem] art:flex-col art:border art:border-border/45 art:bg-background"} initial={{ opacity: 0, y: 24 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.25 }} transition={{ duration: 0.65, delay: reduced ? 0 : index * 0.08, ease: ARTEMIS_EASE_OUT, y: reduced ? { duration: 0 } : undefined }}>
              <div aria-hidden="true" className="art:pointer-events-none art:absolute art:-inset-3 art:text-border-strong">
                <span className="art:absolute art:top-0 art:left-0 art:size-3 art:border-current art:border-t art:border-l"/>
                <span className="art:absolute art:top-0 art:right-0 art:size-3 art:border-current art:border-t art:border-r"/>
                <span className="art:absolute art:bottom-0 art:left-0 art:size-3 art:border-current art:border-b art:border-l"/>
                <span className="art:absolute art:right-0 art:bottom-0 art:size-3 art:border-current art:border-r art:border-b"/>
              </div>
              {plan.featured && <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-x-0 art:top-0 art:h-44 art:bg-[radial-gradient(ellipse_at_top,color-mix(in_oklch,var(--artemis-primary)_22%,transparent),transparent_68%)]"/>}
              <div className="art:relative art:flex art:flex-1 art:flex-col art:p-6 art:@min-[640px]/artemis:p-7">
                <div className="art:flex art:items-start art:justify-between art:gap-4">
                  <div>
                    <p className="art:text-xl art:font-medium art:text-foreground art:tracking-[-0.04em]">
                      {plan.name}
                    </p>
                    {plan.description && <p className="art:mt-3 art:max-w-[17rem] art:font-mono art:text-xs art:text-muted-foreground art:leading-5">
                      {plan.description}
                    </p>}
                  </div>
                  <span aria-hidden="true" className={plan.featured ? "art:mt-1 art:size-2 art:border art:border-primary art:bg-primary" : "art:mt-1 art:size-2 art:border art:border-border-strong art:bg-background"}/>
                </div>
                <div className="art:mt-9 art:min-h-20">
                  {plan.priceLabel !== undefined ? <p className="art:font-mono art:text-3xl art:text-foreground art:tracking-[-0.05em]">
                    {plan.priceLabel}
                  </p> : <span className="art:inline-flex art:items-end art:text-foreground art:tabular-nums art:font-mono art:text-5xl art:tracking-[-0.07em]">
                    <span className="art:self-start art:pt-[0.12em] art:text-base art:text-muted-foreground">
                      {copy.currency}
                    </span>
                    <PriceNumber value={price}/>
                    {plan.period && <span className="art:self-end art:pb-[0.72em] art:pl-1 art:font-sans art:text-base art:text-muted-foreground art:tracking-normal">
                      {plan.period}
                    </span>}
                  </span>}
                  <p className="art:mt-3 art:min-h-4 art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.08em]">
                    {note}
                  </p>
                </div>
                <ul className="art:mt-8 art:space-y-3.5">
                  {plan.features.map((feature, item) => <motion.li key={item} className="art:flex art:items-start art:gap-3 art:font-mono art:text-xs art:text-muted-foreground art:leading-5" initial={{ opacity: 0, x: -8 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true }} transition={{ duration: 0.4, delay: reduced ? 0 : index * 0.08 + item * 0.045, ease: ARTEMIS_EASE_OUT, x: reduced ? { duration: 0 } : undefined }}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={plan.featured ? "art:lucide art:lucide-check art:mt-1 art:size-3 art:shrink-0 art:text-primary" : "art:lucide art:lucide-check art:mt-1 art:size-3 art:shrink-0 art:text-muted-foreground"} aria-hidden="true">
