              </div>
              <div className="art:relative art:border-border/40 art:border-t art:p-3 art:[background-image:repeating-linear-gradient(135deg,color-mix(in_oklch,var(--artemis-foreground)_4%,transparent)_0,color-mix(in_oklch,var(--artemis-foreground)_4%,transparent)_1px,transparent_1px,transparent_7px)]">
                <motion.a whileHover={{ backgroundPosition: "100% 50%" }} transition={ARTEMIS_SPRING_PRESS} className={plan.featured ? "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:px-5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:group/cta art:w-full art:border-0 art:font-mono art:text-xs art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:hover:text-primary-foreground art:h-9 art:rounded-full" : "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:text-foreground art:gap-2 art:px-5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:group/cta art:w-full art:border-0 art:bg-foreground/[0.07] art:font-mono art:text-foreground art:text-xs art:hover:bg-foreground/[0.11] art:h-9 art:rounded-full"} href={plan.cta.href.split("{billing}").join(annual ? "annual" : "monthly")} tabIndex={0}>
                  {plan.cta.label}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3.5 art:transition-transform art:duration-300 art:group-hover/cta:translate-x-0.5 art:group-hover/cta:-translate-y-0.5 art:motion-reduce:transition-none" aria-hidden="true">
                    <path d="M7 7h10v10"/>
                    <path d="M7 17 17 7"/>
                  </svg>
                </motion.a>
              </div>
            </motion.article>;
            })}
          </div>
        </div>
      </section>
    </>);
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "./ease";
export function ArtemisPriceNumber({ value }: { value: number }) {
  const reduce = useReducedMotion() === true;
  const text = String(value);
  return (
    <span className="art:relative art:inline-flex art:h-[1.24em] art:items-center art:overflow-hidden art:px-[0.06em] art:align-bottom">
      <span className="art:sr-only">{text}</span>
      <span aria-hidden className="art:invisible">
        {text}
      </span>
      <AnimatePresence initial={false}>
        <motion.span
          key={text}
          aria-hidden
          className="art:absolute art:inset-y-0 art:right-[0.06em] art:left-[0.06em] art:flex art:items-center art:leading-[1.1]"
          initial={reduce ? { opacity: 0 } : { opacity: 0, y: "55%", filter: "blur(6px)" }}
          animate={{ opacity: 1, y: "0%", filter: "blur(0px)" }}
          exit={reduce ? { opacity: 0 } : { opacity: 0, y: "-55%", filter: "blur(6px)" }}
          transition={{ duration: reduce ? 0 : 0.32, ease: ARTEMIS_EASE_OUT }}
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}
